"use client";

import React, { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import AlumniCard from "@/components/ui/AlumniCard";
import PageHeader from "@/components/layout/PageHeader";
import SearchFilter from "@/components/ui/SearchFilter";

export default function NetworkPage() {
  const { data: session } = useSession();
  const [alumni, setAlumni] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");

  useEffect(() => {
    fetchAlumni();
  }, []);

  const fetchAlumni = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/alumni");
      const data = await res.json();
      if (!data.error) {
        setAlumni(data);
      }
    } catch (error) {
      console.error("Failed to fetch alumni:", error);
    } finally {
      setLoading(false);
    }
  };

  const filteredAlumni = alumni.filter((a) => {
    const matchesSearch =
      a.first_name.toLowerCase().includes(search.toLowerCase()) ||
      a.last_name.toLowerCase().includes(search.toLowerCase()) ||
      a.degree.toLowerCase().includes(search.toLowerCase());

    if (filter === "all") return matchesSearch;
    return matchesSearch && a.connectionStatus === filter;
  });

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#BE123C]"></div>
      </div>
    );
  }

  const filterOptions = [
    { id: "all", label: "All" },
    { id: "connectable", label: "Discover" },
    { id: "pending", label: "Pending" },
    { id: "accepted", label: "Linked" },
  ];

  return (
    <div className="bg-[#F8FAFC] min-h-screen antialiased font-jakarta pb-20">
      <PageHeader
        title="Alumni"
        subtitle="Network"
        description="AConnect Community Hub"
        count={filteredAlumni.length}
        countSuffix="Alumni"
        icon={
          <svg
            className="w-6 h-6 text-amber-400"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="2"
              d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"
            />
          </svg>
        }
      />

      <main className="max-w-6xl mx-auto px-6 pt-4 pb-12">
        <SearchFilter
          search={search}
          onSearchChange={setSearch}
          filter={filter}
          onFilterChange={setFilter}
          filterOptions={filterOptions}
          placeholder="Search by name, degree, or skills..."
        />

        {filteredAlumni.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredAlumni.map((alumnus) => (
              <AlumniCard
                key={alumnus.id}
                alumnus={alumnus}
                onAction={fetchAlumni}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-slate-300">
            <h3 className="text-lg font-bold text-slate-900">
              No matching alumni found
            </h3>
            <p className="text-slate-500 text-sm mt-1">
              Try adjusting your filters or search terms.
            </p>
          </div>
        )}
      </main>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import JobCard from "@/components/ui/JobCard";

export default function JobsPage() {
  const { data: session } = useSession();
  const [jobs, setJobs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [location, setLocation] = useState("");

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    setLoading(true);
    try {
      const query = new URLSearchParams({ search, location });
      const res = await fetch(`/api/jobs?${query}`);
      const data = await res.json();
      if (!data.error) {
        setJobs(data);
      }
    } catch (error) {
      console.error("Failed to fetch jobs:", error);
    } finally {
      setLoading(false);
    }
  };

  const filteredJobs = jobs;

  return (
    <div className="bg-[#FAFAF8] min-h-screen font-sans pb-20">
      <div className="max-w-[1100px] mx-auto px-5 py-5">
        <div className="bg-white p-8 rounded-2xl shadow-md border border-[#E5E7EB] mb-8">
          <form
            onSubmit={(e) => {
              e.preventDefault();
              fetchJobs();
            }}
            className="grid grid-cols-1 md:grid-cols-[1fr_1fr_auto] gap-4 mb-6"
          >
            <div className="relative flex items-center">
              <i className="fas fa-search absolute left-4 text-[#6B7280]"></i>
              <input
                type="text"
                placeholder="Job title or company..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pl-11 pr-4 py-3 bg-[#f9f9f9] border border-[#E5E7EB] rounded-xl focus:outline-none focus:border-[#8B1538] focus:ring-4 focus:ring-[#8B1538]/10 transition-all text-sm"
              />
            </div>
            <div className="relative flex items-center">
              <i className="fas fa-map-marker-alt absolute left-4 text-[#6B7280]"></i>
              <input
                type="text"
                placeholder="City or Remote"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                className="w-full pl-11 pr-4 py-3 bg-[#f9f9f9] border border-[#E5E7EB] rounded-xl focus:outline-none focus:border-[#8B1538] focus:ring-4 focus:ring-[#8B1538]/10 transition-all text-sm"
              />
            </div>
            <button
              type="submit"
              className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] text-white px-8 py-3 rounded-xl font-bold text-sm shadow-sm hover:-translate-y-0.5 hover:shadow-lg transition-all"
            >
              <i className="fas fa-search mr-2"></i> Search
            </button>
          </form>
        </div>

        {loading ? (
          <div className="flex justify-center py-20">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#8B1538]"></div>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredJobs.length > 0 ? (
              filteredJobs.map((job) => <JobCard key={job.id} job={job} />)
            ) : (
              <div className="text-center py-16 bg-white rounded-2xl border border-dashed border-[#E5E7EB] text-[#6B7280]">
                <i className="fas fa-briefcase text-4xl mb-4 opacity-20"></i>
                <p>No Jobs Found</p>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import Link from "next/link";

export default function PeerProfilePage() {
  const { id } = useParams();
  const router = useRouter();
  const { data: session } = useSession();
  const [alumnus, setAlumnus] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);

  useEffect(() => {
    if (id) fetchPeerProfile();
  }, [id]);

  const fetchPeerProfile = async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/alumni/${id}`);
      const data = await res.json();
      if (!data.error) {
        setAlumnus(data);
      } else if (data.isOwnProfile) {
        router.push("/profile");
      }
    } catch (error) {
      console.error("Failed to fetch peer profile:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleConnectionAction = async (action: string) => {
    setActionLoading(true);
    try {
      const res = await fetch("/api/alumni/connection", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action,
          targetId: parseInt(id as string),
          requestId: alumnus.requestId,
        }),
      });
      if (res.ok) {
        fetchPeerProfile();
      }
    } catch (error) {
      console.error("Connection action failed:", error);
    } finally {
      setActionLoading(false);
    }
  };

  const getImagePath = () => {
    if (alumnus?.profile_image)
      return `/assets/uploads/alumni/${alumnus.profile_image}`;
    return `/assets/images/person-${alumnus?.sex?.toLowerCase() === "female" ? "female" : "male"}.png`;
  };

  if (loading || !alumnus) {
    return (
      <div className="flex justify-center items-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#8B1538]"></div>
      </div>
    );
  }

  const employment = alumnus.employment?.[0] || {};

  return (
    <div className="bg-[#FAFAF8] min-h-screen font-sans pb-20 pt-10 px-4">
      <div className="max-w-[900px] mx-auto">
        {}
        <Link
          href="/alumni"
          className="inline-flex items-center gap-2 text-sm font-bold text-[#6B7280] hover:text-[#8B1538] mb-6 transition-colors"
        >
          <i className="fas fa-arrow-left"></i> Back to Network
        </Link>

        {}
        <div className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] h-[180px] rounded-t-2xl relative shadow-md overflow-hidden">
          <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#fff_1px,transparent_1px)] bg-[size:20px_20px]"></div>
        </div>

        {}
        <div className="bg-white p-6 md:p-10 rounded-b-2xl shadow-md relative mb-6">
          <div className="absolute -top-[70px] left-6 md:left-10 w-[140px] h-[140px] rounded-full border-[6px] border-white shadow-xl overflow-hidden bg-white">
            <img
              src={getImagePath()}
              className="w-full h-full object-cover"
              alt="Profile"
              onError={(e) => {
                (e.target as HTMLImageElement).src =
                  `https://ui-avatars.com/api/?name=${alumnus.first_name}+${alumnus.last_name}&background=8B1538&color=fff`;
              }}
            />
          </div>

          <div className="flex flex-col md:flex-row justify-between items-start pt-16 md:pt-0 md:pl-[160px] gap-6">
            <div className="flex-grow">
              <h1 className="text-3xl font-bold text-[#1F2937] mb-1 capitalize">
                {alumnus.first_name} {alumnus.last_name}
              </h1>
              <p className="text-lg text-[#6B7280] font-medium mb-3">
                {alumnus.degree || "Alumni"}
              </p>
              <div className="flex flex-wrap gap-5 text-sm text-[#6B7280]">
                <span className="flex items-center gap-2">
                  <i className="fas fa-graduation-cap text-[#D4A574]"></i>{" "}
                  Graduated {alumnus.graduation_year || "N/A"}
                </span>
                <span className="flex items-center gap-2">
                  <i className="fas fa-id-badge text-[#D4A574]"></i> Class of{" "}
                  {alumnus.year_admitted}
                </span>
              </div>
            </div>

            {}
            <div className="flex gap-3">
              {alumnus.connectionStatus === "accepted" ? (
                <button className="bg-emerald-50 text-emerald-700 px-6 py-3 rounded-xl font-bold text-sm border-2 border-emerald-100 flex items-center gap-2">
                  <i className="fas fa-check-circle"></i> Linked
                </button>
              ) : alumnus.connectionStatus === "pending" ? (
                <button
                  disabled={actionLoading}
                  onClick={() => handleConnectionAction("cancel_request")}
                  className="bg-amber-50 text-amber-700 px-6 py-3 rounded-xl font-bold text-sm border-2 border-amber-100 hover:bg-rose-50 hover:text-rose-700 hover:border-rose-100 transition-all flex items-center gap-2 group"
                >
                  <i className="fas fa-clock group-hover:hidden"></i>
                  <span className="group-hover:hidden">Pending</span>
                  <i className="fas fa-times hidden group-hover:block"></i>
                  <span className="hidden group-hover:block">
                    Cancel Request
                  </span>
                </button>
              ) : alumnus.connectionStatus === "received" ? (
                <div className="flex gap-2">
                  <button
                    disabled={actionLoading}
                    onClick={() => handleConnectionAction("accept_request")}
                    className="bg-emerald-600 text-white px-6 py-3 rounded-xl font-bold text-sm shadow-sm hover:brightness-110 transition-all flex items-center gap-2"
                  >
                    Accept
                  </button>
                  <button
                    disabled={actionLoading}
                    onClick={() => handleConnectionAction("decline_request")}
                    className="bg-rose-600 text-white px-4 py-3 rounded-xl font-bold text-sm shadow-sm hover:brightness-110 transition-all"
                  >
                    <i className="fas fa-times"></i>
                  </button>
                </div>
              ) : (
                <button
                  disabled={actionLoading}
                  onClick={() => handleConnectionAction("send_request")}
                  className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] text-white px-8 py-3 rounded-xl font-bold text-sm shadow-sm hover:-translate-y-0.5 hover:shadow-lg transition-all flex items-center gap-2"
                >
                  <i className="fas fa-user-plus"></i> Connect
                </button>
              )}
            </div>
          </div>
        </div>

        {}
        <div className="grid grid-cols-1 gap-6">
          {}
          <section className="bg-white p-8 rounded-2xl shadow-sm border border-[#E5E7EB]">
            <h3 className="text-xl font-bold text-[#1F2937] mb-6 pb-4 border-b-2 border-[#D4A574] flex items-center gap-3">
              <i className="fas fa-briefcase text-[#8B1538]"></i> Career Summary
            </h3>
            {employment.job_title ? (
              <div className="flex gap-6 items-start">
                <div className="w-14 h-14 bg-slate-100 text-slate-400 rounded-xl flex items-center justify-center text-2xl flex-shrink-0">
                  <i className="fas fa-building"></i>
                </div>
                <div className="flex-grow">
                  <h4 className="text-lg font-bold text-[#1F2937] mb-1">
                    {employment.job_title}
                  </h4>
                  <p className="text-[#6B7280] mb-3">
                    {employment.company_name}
                  </p>
                  <p className="text-sm text-[#4B5563] leading-relaxed line-clamp-3">
                    {employment.job_description ||
                      "Currently pursuing professional growth in this role."}
                  </p>
                </div>
              </div>
            ) : (
              <p className="text-slate-500 italic text-center py-4">
                No professional experience listed
              </p>
            )}
          </section>

          {}
          <section className="bg-white p-8 rounded-2xl shadow-sm border border-[#E5E7EB]">
            <h3 className="text-xl font-bold text-[#1F2937] mb-6 pb-4 border-b-2 border-[#D4A574] flex items-center gap-3">
              <i className="fas fa-award text-[#8B1538]"></i> Professional
              Certifications
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {alumnus.certifications?.length > 0 ? (
                alumnus.certifications.map((cert: any) => (
                  <div
                    key={cert.id}
                    className="p-4 bg-slate-50 rounded-xl border border-slate-100"
                  >
                    <div className="flex gap-3 mb-3">
                      <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center text-[#D4A574] shadow-sm">
                        <i className="fas fa-medal"></i>
                      </div>
                      <div>
                        <h4 className="font-bold text-sm text-[#1F2937]">
                          {cert.name}
                        </h4>
                        <p className="text-[11px] text-[#6B7280]">
                          {cert.issuing_org}
                        </p>
                      </div>
                    </div>
                    {cert.credential_url && (
                      <a
                        href={cert.credential_url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-[10px] font-bold text-[#8B1538] uppercase tracking-widest hover:underline"
                      >
                        Verify Credential{" "}
                        <i className="fas fa-external-link-alt ml-1"></i>
                      </a>
                    )}
                  </div>
                ))
              ) : (
                <p className="col-span-2 text-slate-500 italic text-center py-4">
                  No certifications listed
                </p>
              )}
            </div>
          </section>

          {}
          <section className="bg-white p-8 rounded-2xl shadow-sm border border-[#E5E7EB]">
            <h3 className="text-xl font-bold text-[#1F2937] mb-6 pb-4 border-b-2 border-[#D4A574] flex items-center gap-3">
              <i className="fas fa-shapes text-[#8B1538]"></i> Areas of
              Expertise
            </h3>
            <div className="flex flex-wrap gap-2">
              {alumnus.technical_skills ? (
                alumnus.technical_skills.split(",").map((skill: string) => (
                  <span
                    key={skill}
                    className="px-4 py-2 bg-slate-100 text-[#1F2937] rounded-xl text-xs font-bold border border-slate-200"
                  >
                    {skill.trim()}
                  </span>
                ))
              ) : (
                <p className="text-slate-500 italic">No expertise listed</p>
              )}
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useSession } from "next-auth/react";

export default function ProfilePage() {
  const { data: session } = useSession();
  const [alumni, setAlumni] = useState<any>(null);
  const [certifications, setCertifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeModal, setActiveModal] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({});
  const [certTab, setCertTab] = useState<"credly" | "manual">("credly");
  const [certificationImage, setCertificationImage] = useState<File | null>(
    null,
  );
  const [showSuccessNotification, setShowSuccessNotification] = useState(false);

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/profile");
      const data = await res.json();
      if (!data.error) {
        setAlumni(data);
        setCertifications(data.certifications || []);

        setFormData({
          ...data,
          alternative_phone: data.alternative_phone || "",
          alternative_email: data.alternative_email || "",
          phone: data.phone || "",
          email: data.email || "",
          degree: data.degree || "",
          graduation_year: data.graduation_year || "",
          first_name: data.first_name || "",
          last_name: data.last_name || "",
        });
      }
    } catch (error) {
      console.error("Failed to fetch profile:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleCertificationSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const data = new FormData();

      // If editing, append ID
      if (formData.id) {
        data.append("id", formData.id);
      }

      if (certTab === "credly") {
        // Parse Credly Embed Code if provided
        let processedUrl = formData.credential_url;
        // Basic cleanup of whitespace
        if (processedUrl) processedUrl = processedUrl.trim();

        if (processedUrl && processedUrl.includes("data-share-badge-id")) {
          const match = processedUrl.match(/data-share-badge-id="([^"]+)"/);
          if (match && match[1]) {
            processedUrl = `https://www.credly.com/badges/${match[1]}/public_url`;
          }
        } else if (processedUrl && processedUrl.includes("<iframe")) {
          const match = processedUrl.match(/src="([^"]+)"/);
          if (match && match[1]) {
            if (match[1].includes("embedded_badge")) {
              const id = match[1].split("embedded_badge/")[1];
              processedUrl = `https://www.credly.com/badges/${id}/public_url`;
            } else {
              processedUrl = match[1];
            }
          }
        }

        data.append("name", formData.name);
        data.append("issuing_org", formData.issuing_org);
        data.append("credential_url", processedUrl);
        data.append("credential_id", formData.credential_id || "");
        if (formData.issue_date) data.append("issue_date", formData.issue_date);
        if (formData.expiration_date)
          data.append("expiration_date", formData.expiration_date);
      } else {
        // Manual fields
        data.append("name", formData.name);
        data.append("issuing_org", "Manual Entry");
        data.append("issue_date", formData.issue_date);
        data.append("expiration_date", formData.expiration_date || "");
        if (certificationImage) {
          data.append("certification_image", certificationImage);
        }
      }

      const method = formData.id ? "PUT" : "POST";

      const res = await fetch("/api/profile/certifications", {
        method: method,
        body: data,
      });

      if (res.ok) {
        fetchProfile();
        setActiveModal(null);
        setCertificationImage(null);
        setShowSuccessNotification(true);
        setTimeout(() => setShowSuccessNotification(false), 3000);
      }
    } catch (error) {
      console.error("Failed to save certification:", error);
    }
  };

  const handleDeleteCertification = async (id: number) => {
    if (!confirm("Are you sure you want to delete this certification?")) return;
    try {
      const res = await fetch(`/api/profile/certifications?id=${id}`, {
        method: "DELETE",
      });
      if (res.ok) {
        fetchProfile();
        setShowSuccessNotification(true);
        setTimeout(() => setShowSuccessNotification(false), 3000);
      }
    } catch (error) {
      console.error("Failed to delete certification:", error);
    }
  };

  const handleEditCertification = (cert: any) => {
    setFormData({
      id: cert.id,
      name: cert.name,
      issuing_org: cert.issuing_org,
      issue_date: cert.issue_date
        ? new Date(cert.issue_date).toISOString().split("T")[0]
        : "",
      expiration_date: cert.expiration_date
        ? new Date(cert.expiration_date).toISOString().split("T")[0]
        : "",
      credential_id: cert.credential_id || "",
      credential_url: cert.credential_url || "",
    });

    // Determine tab based on URL or org
    if (cert.credential_url && cert.credential_url.includes("credly.com")) {
      setCertTab("credly");
    } else {
      setCertTab("manual");
    }

    setActiveModal("certification");
  };

  const handleUpdate = async (type: string, payload: any) => {
    try {
      const res = await fetch("/api/profile/update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ type, ...payload }),
      });
      if (res.ok) {
        fetchProfile();
        setActiveModal(null);
        setShowSuccessNotification(true);

        setTimeout(() => {
          setShowSuccessNotification(false);
        }, 3000);
      }
    } catch (error) {
      console.error("Update failed:", error);
    }
  };

  const getImagePath = () => {
    if (alumni?.profile_image)
      return `/assets/uploads/alumni/${alumni.profile_image}`;
    return `/assets/images/person-${alumni?.sex?.toLowerCase() === "female" ? "female" : "male"}.png`;
  };

  const isCredly = (url: string) => {
    return url && url.includes("credly.com");
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const uploadFormData = new FormData();
    uploadFormData.append("file", file);

    try {
      setLoading(true);
      const res = await fetch("/api/profile/upload-image", {
        method: "POST",
        body: uploadFormData,
      });
      const data = await res.json();
      if (data.success) {
        fetchProfile();
      }
    } catch (error) {
      console.error("Image upload failed:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading || !alumni) {
    return (
      <div className="flex justify-center items-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#8B1538]"></div>
      </div>
    );
  }

  const employment = alumni.employment?.[0] || {};

  return (
    <div className="bg-[#FAFAF8] min-h-screen font-sans pb-20 pt-10 px-4">
      <div className="max-w-[900px] mx-auto">
        {}
        <div className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] h-[180px] rounded-t-2xl relative shadow-md overflow-hidden">
          <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#fff_1px,transparent_1px)] bg-[size:20px_20px]"></div>
        </div>

        {}
        <div className="bg-white p-6 md:p-10 rounded-b-2xl shadow-md relative mb-6">
          <div className="absolute -top-[70px] left-6 md:left-10 w-[140px] h-[140px] rounded-full border-[6px] border-white shadow-xl overflow-hidden bg-white">
            <img
              src={getImagePath()}
              className="w-full h-full object-cover"
              alt="Profile"
              onError={(e) => {
                (e.target as HTMLImageElement).src =
                  `https://ui-avatars.com/api/?name=${alumni.first_name}+${alumni.last_name}&background=8B1538&color=fff`;
              }}
            />
          </div>

          <div className="flex flex-col md:flex-row justify-between items-start pt-16 md:pt-0 md:pl-[160px] gap-6">
            <div className="flex-grow">
              <h1 className="text-3xl font-bold text-[#1F2937] mb-1 capitalize">
                {alumni.first_name} {alumni.last_name}
              </h1>
              <p className="text-lg text-[#6B7280] font-medium mb-3">
                {alumni.degree || "Degree Not Set"}
              </p>
              <div className="flex flex-wrap gap-5 text-sm text-[#6B7280]">
                <span className="flex items-center gap-2">
                  <i className="fas fa-graduation-cap text-[#D4A574]"></i>{" "}
                  Graduated {alumni.graduation_year || "N/A"}
                </span>
                <span className="flex items-center gap-2">
                  <i className="fas fa-id-badge text-[#D4A574]"></i> ID:{" "}
                  {alumni.student_number || "N/A"}
                </span>
              </div>
            </div>
            <button
              onClick={() => {
                setFormData(alumni);
                setActiveModal("basic");
              }}
              className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] text-white px-6 py-3 rounded-xl font-bold text-sm shadow-sm hover:-translate-y-0.5 hover:shadow-lg transition-all flex items-center gap-2"
            >
              <i className="fas fa-edit"></i> Edit Profile
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-10 pt-10 border-t border-[#E5E7EB]">
            <div>
              <p className="text-[10px] font-black text-[#6B7280] uppercase tracking-widest mb-2">
                Email
              </p>
              <p className="font-bold text-[#1F2937] break-all">
                {alumni.email || "Not Set"}
              </p>
            </div>
            <div>
              <p className="text-[10px] font-black text-[#6B7280] uppercase tracking-widest mb-2">
                Alternate Email
              </p>
              <p className="font-bold text-[#1F2937] break-all">
                {alumni.alternative_email || "Not Set"}
              </p>
            </div>
            <div>
              <p className="text-[10px] font-black text-[#6B7280] uppercase tracking-widest mb-2">
                Phone
              </p>
              <p className="font-bold text-[#1F2937]">
                {alumni.phone || "Not Set"}
              </p>
            </div>
          </div>
        </div>

        {}
        <div className="grid grid-cols-1 gap-6">
          {}
          <section className="bg-white p-8 rounded-2xl shadow-sm border border-[#E5E7EB] hover:shadow-md transition-all group">
            <div className="flex justify-between items-center mb-6 pb-4 border-b-2 border-[#D4A574]">
              <h3 className="text-xl font-bold text-[#1F2937] flex items-center gap-3">
                <i className="fas fa-briefcase text-[#8B1538]"></i> Employment &
                Career
              </h3>
              <button
                onClick={() => {
                  setFormData(employment);
                  setActiveModal("employment");
                }}
                className="text-[#8B1538] border-2 border-[#8B1538] px-4 py-1.5 rounded-lg text-xs font-bold hover:bg-[#8B1538] hover:text-white transition-all"
              >
                <i className="fas fa-edit mr-2"></i> Edit
              </button>
            </div>

            {employment.job_title ? (
              <div className="flex gap-6 items-start">
                <div className="w-14 h-14 bg-[#8B1538]/10 text-[#8B1538] rounded-xl flex items-center justify-center text-2xl flex-shrink-0">
                  <i className="fas fa-briefcase"></i>
                </div>
                <div className="flex-grow">
                  <h4 className="text-lg font-bold text-[#1F2937] mb-1">
                    {employment.job_title}
                  </h4>
                  <p className="text-[#6B7280] mb-3">
                    {employment.company_name}
                  </p>
                  <div className="flex gap-6 text-xs text-[#6B7280] mb-4">
                    <span className="flex items-center gap-1.5">
                      <i className="fas fa-clock text-[#D4A574]"></i>{" "}
                      {employment.year_of_service} year(s)
                    </span>
                    <span className="flex items-center gap-1.5">
                      <i className="fas fa-arrow-up text-[#D4A574]"></i>{" "}
                      {employment.promotion_count} promotion(s)
                    </span>
                  </div>
                  <span
                    className={`inline-flex items-center gap-2 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${
                      employment.employment_status === "Employed"
                        ? "bg-emerald-100 text-emerald-800"
                        : employment.employment_status === "Self-employed"
                          ? "bg-blue-100 text-blue-800"
                          : "bg-red-100 text-red-800"
                    }`}
                  >
                    <i className="fas fa-circle text-[6px]"></i>{" "}
                    {employment.employment_status}
                  </span>
                </div>
              </div>
            ) : (
              <div className="text-center py-10 text-[#6B7280]">
                <i className="fas fa-briefcase text-4xl mb-4 opacity-10"></i>
                <p className="font-bold text-[#1F2937]">
                  No Employment Info Yet
                </p>
                <p className="text-sm mt-1">
                  Add your current job and career information
                </p>
              </div>
            )}
          </section>

          {}
          <section className="bg-white p-8 rounded-2xl shadow-sm border border-[#E5E7EB] hover:shadow-md transition-all">
            <div className="flex justify-between items-center mb-6 pb-4 border-b-2 border-[#D4A574]">
              <h3 className="text-xl font-bold text-[#1F2937] flex items-center gap-3">
                <i className="fas fa-star text-[#8B1538]"></i> Skills
              </h3>
              <button
                onClick={() => {
                  setFormData({
                    soft_skills: alumni.soft_skills?.split(",") || [],
                    technical_skills: alumni.technical_skills?.split(",") || [],
                  });
                  setActiveModal("skills");
                }}
                className="text-[#8B1538] border-2 border-[#8B1538] px-4 py-1.5 rounded-lg text-xs font-bold hover:bg-[#8B1538] hover:text-white transition-all"
              >
                <i className="fas fa-edit mr-2"></i> Edit
              </button>
            </div>

            <div className="space-y-8">
              <div>
                <h6 className="text-xs font-black text-[#1F2937] uppercase tracking-widest mb-4 flex items-center gap-2">
                  <i className="fas fa-heart text-[#8B1538]"></i> Soft Skills
                </h6>
                <div className="flex flex-wrap gap-2">
                  {alumni.soft_skills ? (
                    alumni.soft_skills.split(",").map((s: string) => (
                      <span
                        key={s}
                        className="bg-gradient-to-br from-[#8B1538]/5 to-[#D4A574]/5 border border-[#E5E7EB] text-[#1F2937] px-4 py-2 rounded-full text-xs font-bold hover:border-[#8B1538] transition-all"
                      >
                        <i className="fas fa-check-circle text-[#8B1538] mr-2"></i>{" "}
                        {s.trim()}
                      </span>
                    ))
                  ) : (
                    <p className="text-xs text-[#6B7280] italic">
                      No soft skills added yet
                    </p>
                  )}
                </div>
              </div>

              <div>
                <h6 className="text-xs font-black text-[#1F2937] uppercase tracking-widest mb-4 flex items-center gap-2">
                  <i className="fas fa-gear text-[#8B1538]"></i> Technical
                  Skills
                </h6>
                <div className="flex flex-wrap gap-2">
                  {alumni.technical_skills ? (
                    alumni.technical_skills.split(",").map((s: string) => (
                      <span
                        key={s}
                        className="bg-gradient-to-br from-[#8B1538]/5 to-[#D4A574]/5 border border-[#E5E7EB] text-[#1F2937] px-4 py-2 rounded-full text-xs font-bold hover:border-[#8B1538] transition-all"
                      >
                        <i className="fas fa-code text-[#8B1538] mr-2"></i>{" "}
                        {s.trim()}
                      </span>
                    ))
                  ) : (
                    <p className="text-xs text-[#6B7280] italic">
                      No technical skills added yet
                    </p>
                  )}
                </div>
              </div>
            </div>
          </section>

          {}
          <section className="bg-white p-8 rounded-2xl shadow-sm border border-[#E5E7EB] hover:shadow-md transition-all">
            <div className="flex justify-between items-center mb-6 pb-4 border-b-2 border-[#D4A574]">
              <h3 className="text-xl font-bold text-[#1F2937] flex items-center gap-3">
                <i className="fas fa-certificate text-[#8B1538]"></i>{" "}
                Certifications
              </h3>
              <button
                onClick={() => {
                  setFormData({
                    name: "",
                    issuing_org: "",
                    issue_date: "",
                    expiration_date: "",
                    credential_id: "",
                    credential_url: "",
                  });
                  setCertificationImage(null);
                  setActiveModal("certification");
                }}
                className="text-[#8B1538] border-2 border-[#8B1538] px-4 py-1.5 rounded-lg text-xs font-bold hover:bg-[#8B1538] hover:text-white transition-all"
              >
                <i className="fas fa-plus mr-2"></i> Add New
              </button>
            </div>

            <div className="space-y-4">
              {certifications.length > 0 ? (
                certifications.map((cert) => (
                  <div
                    key={cert.id}
                    className="flex justify-between items-start p-4 bg-slate-50 rounded-xl border border-slate-100 hover:border-[#D4A574] transition-all group/cert"
                  >
                    <div className="flex gap-4 w-full">
                      <div className="w-12 h-12 bg-[#8B1538]/10 text-[#8B1538] rounded-xl flex items-center justify-center text-xl shadow-sm flex-shrink-0">
                        <i className="fas fa-award"></i>
                      </div>
                      <div className="flex-grow">
                        <h4 className="font-bold text-[#1F2937]">
                          {cert.name}
                        </h4>
                        <p className="text-sm text-[#6B7280] font-medium">
                          {cert.issuing_org}
                        </p>
                        <div className="flex gap-4 mt-2 text-[10px] font-black text-[#9CA3AF] uppercase tracking-widest">
                          <span>
                            Issued:{" "}
                            {cert.issue_date
                              ? new Date(cert.issue_date).toLocaleDateString()
                              : "N/A"}
                          </span>
                          {cert.expiration_date && (
                            <span>
                              Expires:{" "}
                              {new Date(
                                cert.expiration_date,
                              ).toLocaleDateString()}
                            </span>
                          )}
                        </div>
                        {cert.credential_url && (
                          <div className="flex flex-col gap-2 mt-3">
                            <a
                              href={cert.credential_url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-2 text-[#8B1538] text-xs font-bold bg-[#8B1538]/5 px-3 py-1.5 rounded-lg hover:bg-[#8B1538] hover:text-white transition-all shadow-sm w-fit"
                            >
                              <i className="fas fa-external-link-alt"></i> View
                              Credential
                            </a>
                            {isCredly(cert.credential_url) && (
                              <div className="mt-2 border rounded-xl overflow-hidden shadow-sm max-w-[340px] bg-white">
                                <iframe
                                  src={`${cert.credential_url.replace("/public_url", "")}/embed`}
                                  width="340"
                                  height="270"
                                  className="border-0"
                                ></iframe>
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                    <div className="flex items-start gap-2 opacity-0 group-hover/cert:opacity-100 transition-opacity">
                      <button
                        onClick={() => handleEditCertification(cert)}
                        className="text-slate-400 hover:text-blue-600 p-2 transition-transform hover:scale-110"
                        title="Edit Certification"
                      >
                        <i className="fas fa-edit"></i>
                      </button>
                      <button
                        onClick={() => handleDeleteCertification(cert.id)}
                        className="text-slate-400 hover:text-rose-600 p-2 transition-transform hover:scale-110"
                        title="Delete Certification"
                      >
                        <i className="fas fa-trash-alt"></i>
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="text-center py-10 text-[#6B7280]">
                  <div className="w-16 h-16 bg-[#F3F4F6] rounded-full flex items-center justify-center mx-auto mb-4">
                    <i className="fas fa-certificate text-2xl opacity-20"></i>
                  </div>
                  <p className="font-bold text-[#1F2937]">
                    No Certifications Listed
                  </p>
                  <p className="text-sm mt-1">
                    Highlight your professional achievements and credentials
                  </p>
                </div>
              )}
            </div>
          </section>
        </div>
      </div>

      {}
      {activeModal === "basic" && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-3xl w-full max-w-2xl overflow-hidden shadow-2xl">
            <div className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] text-white p-6 flex justify-between items-center">
              <h5 className="font-bold flex items-center gap-3">
                <i className="fas fa-user-circle"></i> Edit Profile Information
              </h5>
              <button onClick={() => setActiveModal(null)} className="text-2xl">
                &times;
              </button>
            </div>
            <div className="p-8 space-y-6">
              <div className="flex flex-col items-center gap-4 py-4 border-b border-[#E5E7EB]">
                <div className="w-[100px] h-[100px] rounded-full overflow-hidden border-4 border-[#8B1538]/20 shadow-inner">
                  <img
                    src={getImagePath()}
                    className="w-full h-full object-cover"
                    alt="Current Profile"
                  />
                </div>
                <label className="cursor-pointer bg-[#8B1538]/5 text-[#8B1538] px-4 py-2 rounded-xl text-xs font-bold hover:bg-[#8B1538]/10 transition-all border border-[#8B1538]/20">
                  <i className="fas fa-camera mr-2"></i> Change Profile Picture
                  <input
                    type="file"
                    className="hidden"
                    accept="image/*"
                    onChange={handleImageUpload}
                  />
                </label>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    First Name
                  </label>
                  <input
                    type="text"
                    value={formData.first_name || ""}
                    onChange={(e) =>
                      setFormData({ ...formData, first_name: e.target.value })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Last Name
                  </label>
                  <input
                    type="text"
                    value={formData.last_name || ""}
                    onChange={(e) =>
                      setFormData({ ...formData, last_name: e.target.value })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-[#1F2937] mb-2">
                  Middle Name (Optional)
                </label>
                <input
                  type="text"
                  value={formData.middle_name || ""}
                  onChange={(e) =>
                    setFormData({ ...formData, middle_name: e.target.value })
                  }
                  className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  placeholder="Leave blank if not applicable"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Degree
                  </label>
                  <input
                    type="text"
                    value={formData.degree || ""}
                    onChange={(e) =>
                      setFormData({ ...formData, degree: e.target.value })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Graduation Year
                  </label>
                  <input
                    type="number"
                    value={formData.graduation_year || ""}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        graduation_year: e.target.value,
                      })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Email
                  </label>
                  <input
                    type="email"
                    value={formData.email || ""}
                    onChange={(e) =>
                      setFormData({ ...formData, email: e.target.value })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Alt Email
                  </label>
                  <input
                    type="email"
                    value={formData.alternative_email || ""}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        alternative_email: e.target.value,
                      })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Phone
                  </label>
                  <input
                    type="text"
                    value={formData.phone || ""}
                    onChange={(e) =>
                      setFormData({ ...formData, phone: e.target.value })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Alt Phone
                  </label>
                  <input
                    type="text"
                    value={formData.alternative_phone || ""}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        alternative_phone: e.target.value,
                      })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-6 border-t border-[#E5E7EB]">
                <button
                  onClick={() => setActiveModal(null)}
                  className="px-6 py-2.5 text-sm font-bold text-[#6B7280] hover:bg-slate-50 rounded-xl"
                >
                  Cancel
                </button>
                <button
                  onClick={() => handleUpdate("basic", formData)}
                  className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] text-white px-8 py-2.5 rounded-xl font-bold text-sm"
                >
                  Save Changes
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeModal === "employment" && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-3xl w-full max-w-2xl overflow-hidden shadow-2xl">
            <div className="bg-gradient-to-br from-[#8B1538] to-[#6B0F2A] text-white p-6 flex justify-between items-center">
              <h5 className="font-bold flex items-center gap-3">
                <i className="fas fa-briefcase"></i> Edit Employment Information
              </h5>
              <button onClick={() => setActiveModal(null)} className="text-2xl">
                &times;
              </button>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-xs font-bold text-[#1F2937] mb-2">
                  Employment Status
                </label>
                <select
                  value={formData.employment_status || ""}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      employment_status: e.target.value,
                    })
                  }
                  className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                >
                  <option value="">-- Select Status --</option>
                  <option value="Employed">Employed</option>
                  <option value="Unemployed">Unemployed</option>
                  <option value="Self-employed">Self-employed</option>
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Job Title
                  </label>
                  <input
                    type="text"
                    value={formData.job_title || ""}
                    onChange={(e) =>
                      setFormData({ ...formData, job_title: e.target.value })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Company Name
                  </label>
                  <input
                    type="text"
                    value={formData.company_name || ""}
                    onChange={(e) =>
                      setFormData({ ...formData, company_name: e.target.value })
                    }
                    className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-[#1F2937] mb-2">
                  Job Description
                </label>
                <textarea
                  value={formData.job_description || ""}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      job_description: e.target.value,
                    })
                  }
                  className="w-full border border-[#E5E7EB] rounded-xl px-4 py-2.5 text-sm min-h-[100px]"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-[#1F2937] mb-2">
                    Years of Service
                  </label>
                  <input
                    type="number"
                    value={formData.year_of_service || 0}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        year_of_service: e.target.value,
                      })
                    }
